from typing import List

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n, m = len(nums), len(changeIndices)

        def can(t: int) -> bool:
            last = [-1] * n
            for i in range(t):
                last[changeIndices[i] - 1] = i + 1  # 1-indexed time

            # Every index must appear at least once in the first t seconds
            for x in last:
                if x == -1:
                    return False

            tasks = sorted((last[i], nums[i] + 1) for i in range(n))
            used = 0
            for deadline, need in tasks:
                used += need
                if used > deadline:
                    return False
            return True

        if not can(m):
            return -1

        lo, hi = 1, m
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
```

